INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swords and Sandals 5 Redux', 'Gladiator, it is time to go underground! For the first time ever, you shall step beyond the arena sands and into the dark dungeons of the world.Swords and Sandals V Redux, the latest thrilling installment in the world''s greatest gladiator game series, has arrived! A unique mix of turn based gladiatorial arena combat and roguelike dungeon crawling.This is by far the largest and greatest Swords and Sandals adventure ever made. Only the greatest gladiators will survive the dark. Will you stand among the brave few?' FROM games WHERE igdb_id = 81817 ON CONFLICT (game_id, language_code) DO NOTHING;
