INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tap Empire', 'Tap your way to a billionaire monopoly! Serve Piggy B, help make him rich and famous. Whether you''re an active tapper or a passive idler your business will thrive in Tap Empire. Unlock addictive new worlds, build an empire, collect magic items, and supercharge your robots as you work to amass untold riches. Everyone is counting on you to topple greedy Mr. Bossworth''s evil empire!' FROM games WHERE igdb_id = 110042 ON CONFLICT (game_id, language_code) DO NOTHING;
