INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haunted Corny Maize', 'Welcome to Bailey''s Corn Maze! Where during this autumn season you can explore a fun little maze and maybe find a bit of romance along the way. Play as a young woman venturing into the maze all by herself, but with the chance of running into a few monstrous maids that are dealing with some issues ranging from mundane inconveniences to their own personality quirks getting in the way to being literally trapped in the maze until someone rescues them.' FROM games WHERE igdb_id = 178906 ON CONFLICT (game_id, language_code) DO NOTHING;
