INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('silverstarchess', 147986, '2018-05-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30py.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arax4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SilverStarChess', 'One of the standard board games in the “SilverStar” Series of SilverStarJapan Our latest offering: the game of chess. The top-class “SilverStar” board game engine also plays outstanding chess games. We are proud to recommend this game for both veteran chess players and beginners. Sharing enabled Share the Joy-Con with another player to play head-to-head or play a match against the computer. Touch screen compatible This game responds to touch controls to provide more comfortable play. Display available pieces Available pieces for a specific square are highlighted. Hint function The computer’s recommended move can be displayed. Score management Store up to 100 game records. You can resume from the desired position by loading the stored game data. List of Functions Head-to-head match Hint function Pause BGM and sound effects ON/OFF Check display ON/OFF Available squares ON/OFF Coordinates ON/OFF Available pieces ON/OFF Adjust piece movement speed The game is called a draw when the number of moves reaches 200.' FROM games WHERE igdb_id = 147986 ON CONFLICT (game_id, language_code) DO NOTHING;
