INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zquirrels Jump', 'Why do Zquirrels Jump? Why do they risk their health and life? In the name and glory of the one and only true love. The love for peanuts! Join the Zquirrels, strap in and jump. You have only a few seconds before the nuts hit the ground. Make us proud, jump now!' FROM games WHERE igdb_id = 111245 ON CONFLICT (game_id, language_code) DO NOTHING;
