INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fast Food 64: Holiday Snacks', 'Make no mistake, Fast Food 64: Holiday Snacks is not just a Christmas re-skin of Fast Food 64. It is a BRAND NEW game with an entirely new code base written from the ground up. FAST FOOD 64 has returned for a Holiday inspired TRUE sequel! In Fast Food 64: Holiday Snacks you can play in one of 3 exciting arcade style game modes! The game also features a Christmas techno soundtrack with 5 music tracks, all of which are MP3 quality sound! You will hear these jamming beats in the different game modes, or you can listen to them as you wish in the games'' Music Test Mode.' FROM games WHERE igdb_id = 301786 ON CONFLICT (game_id, language_code) DO NOTHING;
