INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Happy Birthdays', 'From legendary creator Mr. Yasuhiro Wada (TOYBOX Inc.) comes Happy Birthdays: a sandbox game in which players create cube-shaped worlds that give rise to diverse and unique lifeforms. With careful experimentation, players can shape the geography and alter the temperature of the world to create the conditions for life and witness the birth of an entire ecosystem!' FROM games WHERE igdb_id = 86771 ON CONFLICT (game_id, language_code) DO NOTHING;
