INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pan-Dimensional Conga Combat', 'Developed in a top secret lab over the course of the past eighteen months, RGCD.DEV''s Pan-Dimensional Conga Combat is a rhythm-synchronised, old-school, score-chasing arcade game that plays like some alien coin-op from another dimension. Grab your Conganoid and join the Elder Gods in the competitive ceremonial slaughter of annoyingly happy (yet extremely deadly) geometric, pan-dimensional critters!' FROM games WHERE igdb_id = 86253 ON CONFLICT (game_id, language_code) DO NOTHING;
